"""GENERATED by scripts/make_bay_cad_fusion.py -- do not edit this file.

Every number below comes from design/bay.py. Regenerate rather than patch.

Bay      shell OD 74.500 mm, ID 69.700 mm, Z 53.13 -> 94.63
Collars  4 x dia 12.0 boss, dia 8.00 bore (as reamed), at Z 68.27
Trays    4 x servo window 24.10 x 8.60 mm, R 27.94 -> 31.94
Screws   Z 60.63 / 87.13, insert dia 3.2 at Y +/-6.0
Retainer 8 x dog-bone bar, 1.5 mm thick, R 25.435 -> 26.935
Volume   canard bay 28889.0 mm3 (+/-6%), one retainer bar 90.8076 mm3
"""


import math

import adsk.core
import adsk.fusion


def _box(tbm, cx, cy, cz, lx, ly, lz):
    """An axis-aligned box in the GLOBAL X/Y/Z frame. mm in, cm internally."""
    obb = adsk.core.OrientedBoundingBox3D.create(
        adsk.core.Point3D.create(cx / 10.0, cy / 10.0, cz / 10.0),
        adsk.core.Vector3D.create(1.0, 0.0, 0.0),
        adsk.core.Vector3D.create(0.0, 1.0, 0.0),
        lx / 10.0, ly / 10.0, lz / 10.0)
    return tbm.createBox(obb)


def _cyl(tbm, x, y, z0, z1, r):
    """A cylinder on an axis PARALLEL TO Z, from z0 to z1. mm in, cm internally."""
    return tbm.createCylinderOrCone(
        adsk.core.Point3D.create(x / 10.0, y / 10.0, z0 / 10.0), r / 10.0,
        adsk.core.Point3D.create(x / 10.0, y / 10.0, z1 / 10.0), r / 10.0)


def _quadrant_axes(quadrant):
    """u = radial direction, v = tangential direction, at 90 deg * quadrant about Z."""
    a = math.radians(quadrant * 90.0)
    u = adsk.core.Vector3D.create(math.cos(a), math.sin(a), 0.0)
    v = adsk.core.Vector3D.create(-math.sin(a), math.cos(a), 0.0)
    return u, v


def _quadrant_box(tbm, quadrant, r_lo, r_hi, y_lo, y_hi, z_lo, z_hi):
    """A box whose length runs radially and width tangentially, at a given quadrant
    (0/1/2/3 = 0/90/180/270 deg about the rocket Z axis) -- ports
    `cad/canard_bay.fs`'s `quadrantCuboid`. mm in, cm internally.
    """
    u, v = _quadrant_axes(quadrant)
    r_lo, r_hi = min(r_lo, r_hi), max(r_lo, r_hi)
    y_lo, y_hi = min(y_lo, y_hi), max(y_lo, y_hi)
    z_lo, z_hi = min(z_lo, z_hi), max(z_lo, z_hi)
    rc, yc, zc = (r_lo + r_hi) / 2.0, (y_lo + y_hi) / 2.0, (z_lo + z_hi) / 2.0
    center = adsk.core.Point3D.create(
        (u.x * rc + v.x * yc) / 10.0, (u.y * rc + v.y * yc) / 10.0, zc / 10.0)
    obb = adsk.core.OrientedBoundingBox3D.create(
        center, u, v, (r_hi - r_lo) / 10.0, (y_hi - y_lo) / 10.0, (z_hi - z_lo) / 10.0)
    return tbm.createBox(obb)


def _radial_cyl(tbm, quadrant, across, z, r0, r1, r):
    """A cylinder on a RADIAL axis at the given quadrant, spanning radius r0 -> r1, offset
    `across` tangentially -- ports `cad/canard_bay.fs`'s `radialCylinder`. mm in, cm
    internally.
    """
    u, v = _quadrant_axes(quadrant)
    bx, by = v.x * across, v.y * across
    p0 = adsk.core.Point3D.create((bx + u.x * r0) / 10.0, (by + u.y * r0) / 10.0, z / 10.0)
    p1 = adsk.core.Point3D.create((bx + u.x * r1) / 10.0, (by + u.y * r1) / 10.0, z / 10.0)
    return tbm.createCylinderOrCone(p0, r / 10.0, p1, r / 10.0)


def _cut(tbm, target, tool, what):
    """Boolean subtract. NOTE: booleanOperation returns a BOOL and mutates `target` in
    place -- never assign its result back, per make_sled_fusion.py's own warning.
    """
    if not tbm.booleanOperation(target, tool, adsk.fusion.BooleanTypes.DifferenceBooleanType):
        raise ValueError("cut %s did not take" % what)


def _union(tbm, target, tool, what):
    if not tbm.booleanOperation(target, tool, adsk.fusion.BooleanTypes.UnionBooleanType):
        raise ValueError("union %s did not take" % what)


def _get_or_create_component(root, name):
    """Find an existing occurrence by component name, else create a new empty one.

    Returns (occurrence, already_has_bodies). A caller that finds `already_has_bodies`
    True should verify rather than rebuild -- the same idempotency rule
    `make_sled_fusion.py` uses.
    """
    for o in root.occurrences:
        if o.component.name == name:
            return o, o.component.bRepBodies.count > 0
    occ = root.occurrences.addNewComponent(adsk.core.Matrix3D.create())
    occ.component.name = name
    return occ, False


def _inject(comp, made):
    """Inject a list of (name, body) temporary BRep bodies through one BaseFeature.

    Mandatory for a parametric document: a temp body only "takes" via
    `BRepBodies.add(body, baseFeature)`, per make_sled_fusion.py's own header.
    """
    bf = comp.features.baseFeatures.add()
    bf.startEdit()
    for (name, body) in made:
        b = comp.bRepBodies.add(body, bf)
        b.name = name
    bf.finishEdit()


def _verify_volume(comp, want, tol, loose=(), loose_tol=None):
    """Compare each named body's volume (mm3) against an analytic expectation.

    `loose` names bodies (radial holes through curved walls, or a part whose analytic
    figure is itself an estimate) that get `loose_tol` instead of `tol` -- measured, not
    guessed, the same discipline make_sled_fusion.py's PORT_VOLUME_TOLERANCE_PER_PORT uses.
    Returns a list of violation strings (empty if everything is within tolerance).
    """
    acc = adsk.fusion.CalculationAccuracy.VeryHighCalculationAccuracy
    got = {}
    for b in comp.bRepBodies:
        got[b.name] = b.getPhysicalProperties(acc).volume * 1e3
    bad = []
    for name, wv in want.items():
        if name not in got:
            bad.append("%s is missing" % name)
            continue
        t = loose_tol if (name in loose and loose_tol is not None) else tol
        d = got[name] - wv
        print("  %-28s %14.4f mm3  want %14.4f  delta %+9.4f  (tol %.3f)"
              % (name, got[name], wv, d, t))
        if abs(d) > t:
            bad.append("%s is %+.4f mm3 out" % (name, d))
    return bad


def _verify_cyl_faces(body, radius, axis_is_radial):
    """Count cylindrical faces at `radius` (mm) and read back their clocking, in degrees
    mod 180. `axis_is_radial` True keeps only faces whose axis has no Z component (a
    radial hole); False keeps only faces whose axis IS parallel to Z (an axial hole).
    Exact where a volume check on a radial hole through a curved wall is not -- see
    make_sled_fusion.py's header for why that matters.
    """
    found = []
    for f in body.faces:
        g = f.geometry
        if not g.objectType.endswith("Cylinder"):
            continue
        if abs(g.radius * 10.0 - radius) > 1e-6:
            continue
        ax = g.axis
        is_radial = abs(ax.z) < 1e-9
        if is_radial != axis_is_radial:
            continue
        found.append(math.degrees(math.atan2(ax.y, ax.x)) % 180.0)
    return sorted(found)


COMPONENT = 'CanardBay'
OVER = 1.0   # mm, overshoot on every cut/join -- see fusion_common.py's header

SHELL_OD = 74.5000
SHELL_ID = 69.7000
Z_FWD = 53.1290
Z_AFT = 94.6290
Z_HINGE = 68.2690

COLLAR_OD = 12.0000
COLLAR_BORE = 8.0000
COLLAR_OVERLAP = 0.5000
COLLAR_INNER_R = 33.7000

TRAY_FLANGE_R = 27.9350
TRAY_BACK_R = 31.9350
TRAY_WIDTH = 18.4000
TRAY_FWD_Z = 59.1290
TRAY_AFT_Z = 88.6290

WINDOW_LEN = 24.1000
WINDOW_WID = 8.6000
WINDOW_FWD_Z = 61.8290

WEB_THK = 1.6000
BOSS_FACE_R = 26.9350
INSERT_DIA = 3.2000
INSERT_DEPTH = 4.0000
CLAMP_Y = 6.0000
SCREW_Z1 = 60.6290
SCREW_Z2 = 87.1290

RET_THK = 1.5000
RET_BRIDGE_HALF_Z = 1.3000
RET_PAD_HALF_Z = 2.3500

BAY_VOLUME_MM3 = 28889.0451
BAR_VOLUME_MM3 = 90.8076
BAY_VOLUME_TOLERANCE = 1733.3427
BAR_VOLUME_TOLERANCE = 0.0100


def run(_context: str):
    app = adsk.core.Application.get()
    des = adsk.fusion.Design.cast(app.activeProduct)
    root = des.rootComponent
    tbm = adsk.fusion.TemporaryBRepManager.get()

    occ, has_bodies = _get_or_create_component(root, COMPONENT)
    if has_bodies:
        print("%s already holds %d bodies -- verifying rather than rebuilding"
              % (COMPONENT, occ.component.bRepBodies.count))
        verify(occ.component)
        return
    comp = occ.component

    made = []

    # ---- 1. the shell, hollowed ----
    shell = _cyl(tbm, 0.0, 0.0, Z_FWD, Z_AFT, SHELL_OD / 2.0)
    _cut(tbm, shell, _cyl(tbm, 0.0, 0.0, Z_FWD - OVER, Z_AFT + OVER, SHELL_ID / 2.0), "hollow")

    # ---- 2. additive bodies, four quadrants -- shell must gain these BEFORE section 3
    #         cuts, or the cuts have nothing to remove material from at those radii ----
    for q in range(4):
        collar = _radial_cyl(tbm, q, 0.0, Z_HINGE, COLLAR_INNER_R,
                              SHELL_ID / 2.0 + COLLAR_OVERLAP, COLLAR_OD / 2.0)
        _union(tbm, shell, collar, "collar %d" % q)

        tray = _quadrant_box(tbm, q, TRAY_FLANGE_R, TRAY_BACK_R,
                              -TRAY_WIDTH / 2.0, TRAY_WIDTH / 2.0, TRAY_FWD_Z, TRAY_AFT_Z)
        _union(tbm, shell, tray, "tray %d" % q)

        for sgn in (1.0, -1.0):
            y_outer = sgn * TRAY_WIDTH / 2.0
            y_inner = y_outer - sgn * WEB_THK
            web = _quadrant_box(tbm, q, TRAY_BACK_R, SHELL_ID / 2.0 + OVER,
                                 y_inner, y_outer, TRAY_FWD_Z, TRAY_AFT_Z)
            _union(tbm, shell, web, "web %d %s" % (q, "p" if sgn > 0 else "m"))

        for k, z_row in enumerate((SCREW_Z1, SCREW_Z2)):
            z_lo = max(z_row - INSERT_DIA, TRAY_FWD_Z)
            z_hi = min(z_row + INSERT_DIA, TRAY_AFT_Z)
            boss = _quadrant_box(tbm, q, BOSS_FACE_R, TRAY_FLANGE_R,
                                  -TRAY_WIDTH / 2.0, TRAY_WIDTH / 2.0, z_lo, z_hi)
            _union(tbm, shell, boss, "boss %d row%d" % (q, k))

    # ---- 3. subtractive bodies, four quadrants ----
    for q in range(4):
        bore = _radial_cyl(tbm, q, 0.0, Z_HINGE, COLLAR_INNER_R - OVER,
                            SHELL_OD / 2.0 + OVER, COLLAR_BORE / 2.0)
        _cut(tbm, shell, bore, "collar bore %d" % q)

        window = _quadrant_box(tbm, q, BOSS_FACE_R - OVER, TRAY_BACK_R + OVER,
                                -WINDOW_WID / 2.0, WINDOW_WID / 2.0,
                                WINDOW_FWD_Z, WINDOW_FWD_Z + WINDOW_LEN)
        _cut(tbm, shell, window, "window %d" % q)

        flange = _quadrant_box(tbm, q, BOSS_FACE_R - OVER, TRAY_FLANGE_R,
                                -WINDOW_WID / 2.0, WINDOW_WID / 2.0,
                                TRAY_FWD_Z - OVER, TRAY_AFT_Z + OVER)
        _cut(tbm, shell, flange, "flange relief %d" % q)

        for k, z_row in enumerate((SCREW_Z1, SCREW_Z2)):
            for sgn in (1.0, -1.0):
                ins = _radial_cyl(tbm, q, sgn * CLAMP_Y, z_row,
                                   BOSS_FACE_R - OVER, BOSS_FACE_R + INSERT_DEPTH,
                                   INSERT_DIA / 2.0)
                _cut(tbm, shell, ins, "insert %d row%d %s" % (q, k, "p" if sgn > 0 else "m"))

    made.append(("canard bay", shell))

    # ---- 4. eight retainer bars, drawn directly per (quadrant, screw row) -- see the
    #         module docstring for why this isn't one bar instanced eight times ----
    r_in = BOSS_FACE_R - RET_THK
    r_out = BOSS_FACE_R
    y_flange = WINDOW_WID / 2.0
    y_outer = TRAY_WIDTH / 2.0
    for q in range(4):
        for k, z_row in enumerate((SCREW_Z1, SCREW_Z2)):
            bar = _quadrant_box(tbm, q, r_in, r_out, -y_flange, y_flange,
                                 z_row - RET_BRIDGE_HALF_Z, z_row + RET_BRIDGE_HALF_Z)
            for sgn in (1.0, -1.0):
                pad = _quadrant_box(tbm, q, r_in, r_out, sgn * y_flange, sgn * y_outer,
                                     z_row - RET_PAD_HALF_Z, z_row + RET_PAD_HALF_Z)
                _union(tbm, bar, pad, "retainer pad q%dr%d" % (q, k))
            for sgn in (1.0, -1.0):
                hole = _radial_cyl(tbm, q, sgn * CLAMP_Y, z_row, r_in - OVER, r_out + OVER,
                                    INSERT_DIA * 0.7 / 2.0)
                _cut(tbm, bar, hole, "retainer hole q%dr%d" % (q, k))
            made.append(("retainer bar q%dr%d" % (q, k), bar))

    _inject(comp, made)
    print("built %d bodies in %s" % (len(made), COMPONENT))
    verify(comp)


def verify(comp):
    """Volume against design/bay.py's analytic figure, plus a face check on the collar
    bores that a volume check cannot make exact -- see fusion_common.py's header and
    make_sled_fusion.py's for why a radial hole through a curved wall needs one.
    """
    want = {"canard bay": BAY_VOLUME_MM3}
    for q in range(4):
        for k in range(2):
            want["retainer bar q%dr%d" % (q, k)] = BAR_VOLUME_MM3
    bad = _verify_volume(comp, want, BAR_VOLUME_TOLERANCE,
                         loose=("canard bay",), loose_tol=BAY_VOLUME_TOLERANCE)

    bay_body = None
    for b in comp.bRepBodies:
        if b.name == "canard bay":
            bay_body = b
    if bay_body is None:
        bad.append("canard bay body is missing, so its collar bores cannot be checked")
    else:
        found = _verify_cyl_faces(bay_body, COLLAR_BORE / 2.0, axis_is_radial=True)
        print("  %-28s %d collar-bore faces at dia %.2f, axes %s deg"
              % ("canard bay", len(found), COLLAR_BORE, ["%.2f" % v for v in found]))
        if len(found) != 4:
            bad.append("canard bay has %d collar-bore faces, wanted 4" % len(found))
        else:
            for a in found:
                if min(abs(a - 0.0), abs(a - 90.0)) > 1e-6:
                    bad.append("a collar bore is clocked %.4f deg, wanted 0 or 90" % a)

    if bad:
        raise ValueError("VERIFY FAILED: " + "; ".join(bad))
    print("  OK")
